"""Publish measured comparisons, including the failed domain-shift checks."""
import json
from pathlib import Path
import pandas as pd

BASE=Path(__file__).resolve().parent

if __name__=="__main__":
    old=json.loads((BASE/"trained_expanded/training_completed.json").read_text())
    new=json.loads((BASE/"trained_semantic/training_completed.json").read_text())
    final=json.loads((BASE/"final_test/evaluation.json").read_text())
    diagnostic=json.loads((BASE/"trained_semantic/taco_diagnostic/evaluation.json").read_text())
    regression=json.loads((BASE/"trained_semantic/old_10_regression.json").read_text())
    bottle=json.loads((BASE/"trained_semantic/bottle_regression.json").read_text())
    settings=json.loads((BASE/"trained_semantic/app_settings.json").read_text())
    before=next(row for row in old["test_metrics"] if row["model"]==old["selected"])
    lines=["# EcoSort Accuracy Improvement", "", "## Measured Results", "", "| Evaluation | Original MobileNet | Full-object semantic ensemble |", "|---|---:|---:|", f"| Same 14,712-image, 17-class public test accuracy | {before['accuracy']:.2%} | {new['test_metrics']['accuracy']:.2%} |", f"| Same public test macro-F1 | {before['macro_f1']:.4f} | {new['test_metrics']['macro_f1']:.4f} |", f"| New 30 whole photos, first pass | {final['old_correct']}/30 ({final['old_accuracy']:.2%}) | {final['correct']}/30 ({final['accuracy']:.2%}) |", f"| Original ten photos, regression only | 5/10 | {regression['correct']}/10 |", f"| TACO 55 crops, development diagnostic | {diagnostic['old_correct']}/55 ({diagnostic['old_accuracy']:.2%}) | {diagnostic['correct']}/55 ({diagnostic['accuracy']:.2%}) |", "", "The >=80% target is met on the public test and the frozen thirty-photo panel, not on every evaluated domain. Complex litter scenes remain below target and are a known limitation. Accuracy includes all samples, even those marked for manual review. The final thirty photos cover ten common categories, not all seventeen, and are a convenience sample, not Sydney-local validation or a guarantee for future images. Foundation-model pretraining membership is unknown.", "", "## What Changed", "", "A pinned, SHA-256-verified OpenCLIP ViT-B-32 encoder provides general visual features. A regularized classification head is trained on all 117,893 training images. Validation selects the head and combination with the unchanged fine-tuned MobileNet; test labels never update weights. The deployed class count and source split are unchanged. All inference remains on this Mac.", "", f"Selected probability weights [MobileNet, trained semantic head, zero-shot]: {settings['weights']}. Regularization C={settings['linear_C']}. Feature preprocessing: {settings['preprocess_version']}. This run took {new['seconds']/60:.2f} minutes for feature extraction, head fitting, calibration and internal evaluation; model download and photo collection are excluded.", "", "The initial center-crop experiment reached 86.83% internally but only 32/55 on the first TACO panel. It was not deployed. Inspection showed that center cropping can remove a narrow bottle's top and bottom. Full-object letterboxing replaced it in both training and inference; a synthetic 1:4-object check verifies both ends remain. All features and heads were rebuilt. The initial experiment is preserved in trained_semantic_center_crop/ and fresh_test/evaluation.json. Its TACO panel became development data after that diagnosis and is never called independent evidence again.", "", "The final thirty unmodified whole photos were visually reviewed and frozen after duplicate checks against the full raw project pool and the original ten test photos, before any model prediction. Unrelated scenes, drawings, ambiguous labels and repeated views were excluded before prediction, not because of an incorrect score. Each of the ten target categories has three photos. Source URLs, authors, licences, hashes and sampling limits are preserved in final_test/test_manifest.json. Selection is not representative random sampling of all household waste.", "", "## Final Panel Errors", ""]
    errors=pd.read_csv(BASE/"final_test/predictions.csv")
    for row in errors[~errors.correct].itertuples():
        lines.append(f"- {row.id}: expected {row.expected_label}, predicted {row.predicted}, score {row.confidence:.1%}, manual review {row.manual_review}.")
    lines.extend(["", "## Original Bottle", "", f"Expected plastic; predicted {bottle['predicted']}; score {bottle['confidence']:.1%}; review flag {bottle['manual_review']}. The score for one image is not overall model accuracy. Disposal still requires item-specific conditions; no image can prove a container is empty.", "", "## Running and Verification", "", "Use http://127.0.0.1:7861/. active_model.json identifies the deployed results folder. ECOSORT_Local_Run.ipynb reads that pointer. ECOSORT_Accuracy_Improvement.ipynb documents the workflow in English text/code sections. Historical Colab files and previous measurements remain unchanged. Accuracy UI/camera checks are recorded separately in accuracy_ui_verification.json when completed.", "", "## Still Required", "", "Collect and label 50-100 independent Sydney-local photos, address background/domain shift with training-only data and a new untouched test set, and review ambiguous material labels. This does not finish the original proposal's batch-contamination calculation, LLM summary evaluation or final team report. Do not tune on these thirty final photos and continue presenting them as independent.", "", "Sources: [OpenCLIP official implementation](https://github.com/mlfoundations/open_clip), [pinned weights](https://huggingface.co/laion/CLIP-ViT-B-32-laion2B-s34B-b79K/tree/1a25a446712ba5ee05982a381eed697ef9b435cf), [TACO source annotations](https://github.com/pedropro/TACO/blob/master/data/annotations.json). Whole-photo attributions are listed individually in the frozen final manifest. Review image rights before redistribution.", ""])
    per_class=pd.read_csv(BASE/"trained_semantic/classification_report.csv",index_col=0)
    lines.extend(["## Per-Class Qualification", "", f"Overall accuracy above 80% does not imply every category exceeds 80%. Plastic recall is {per_class.loc['plastic','recall']:.2%} and precision is {per_class.loc['plastic','precision']:.2%}. Metal recall and cardboard precision also remain below 80%. See trained_semantic/classification_report.csv for every category. This is a measured improvement, not a category-by-category guarantee.", ""])
    ui_path=BASE/"accuracy_ui_verification.json"
    if ui_path.exists():
        ui=json.loads(ui_path.read_text())
        lines.extend(["## Completed UI Checks", "", f"The deployed model completed actual webcam capture and file-upload prediction. Camera frames were {ui['camera_video']['width']} x {ui['camera_video']['height']}; camera capture and prediction completed. Camera accuracy was not assessed for the unlabeled smoke-test frame. The camera was closed afterward. The original bottle displayed Plastic (61.8%) with conditional official-source guidance. See accuracy_ui_verification.json and accuracy_improved_app.png.", ""])
    (BASE/"ACCURACY_IMPROVEMENT_REPORT.md").write_text("\n".join(lines))
    print(BASE/"ACCURACY_IMPROVEMENT_REPORT.md")
